import { drizzle } from "drizzle-orm/node-postgres";
import pg from "pg";
import * as schema from "./schema/index.js";
import dotenv from "dotenv";

dotenv.config();

const { Pool } = pg;

if (!process.env.DATABASE_URL) {
  throw new Error(
    "DATABASE_URL must be set. Did you forget to provision a database?",
  );
}

export const pool = new Pool({ connectionString: process.env.DATABASE_URL });
export const db = drizzle(pool, { schema });

export { usersTable } from "./schema/users.js";
export { accountsTable } from "./schema/accounts.js";
export { transactionsTable } from "./schema/transactions.js";
export { cryptoTransactionsTable, cryptoHoldingsTable } from "./schema/crypto.js";
export { siteSettingsTable } from "./schema/settings.js";
export { cardsTable } from "./schema/cards.js";
